        &lt;/td&gt;
      &lt;/tr&gt;

      &lt;tr&gt;
        &lt;td&gt;Username:&lt;/td&gt;
        &lt;td&gt;&lt;input type="text" size=25 name="userid"&gt;&lt;/td&gt;
      &lt;/tr&gt;

      &lt;tr&gt;
        &lt;td&gt;Password:&lt;/td&gt;
        &lt;td&gt;&lt;input type="Password" size=25 name="pwd"&gt;&lt;/td&gt;
